new_section = b"""// \xe2\x94\x80\xe2\x94\x80\xe2\x94\x80 Questions \xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\nconst Questions = {\n  template: `\n    <div class="p-8">\n      <h1 class="text-3xl font-bold mb-6">\xeb\xac\xb8\xec\xa0\x9c\xec\x9d\x80\xed\x96\x89</h1>\n\n      <!-- \xeb\xac\xb8\xec\x84\x9c/\xeb\xaa\xa8\xeb\x8d\xb8 \xec\x84\xa0\xed\x83\x9d \xed\x8c\xa8\xeb\x84\x90 -->\n      <div v-if="docSelectorOpen" class="fixed inset-0 z-20" @click="docSelectorOpen = false"></div>\n      <div class="bg-white rounded-xl shadow p-6 mb-6">\n        <div class="flex flex-wrap items-center gap-4">\n          <div class="relative flex items-center gap-2">\n            <span class="text-sm font-medium text-gray-500">\xeb\xac\xb8\xec\x84\x9c:</span>\n            <div class="relative z-30">\n              <button @click="docSelectorOpen = !docSelectorOpen"\n                class="border border-gray-300 rounded-lg px-3 py-2 text-sm bg-white flex items-center gap-2 min-w-[180px] justify-between hover:border-purple-400 transition-colors">\n                <span class="truncate">{{ selectedDocIds.length === 0 ? \'\xeb\xac\xb8\xec\x84\x9c\xeb\xa5\xbc \xec\x84\xa0\xed\x83\x9d\xed\x95\x98\xec\x84\xb8\xec\x9a\x94\' : selectedDocIds.length + \'\xea\xb0\x9c \xeb\xac\xb8\xec\x84\x9c \xec\x84\xa0\xed\x83\x9d\xeb\x90\xa8\' }}</span>\n                <svg class="w-4 h-4 text-gray-400 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"/></svg>\n              </button>\n              <div v-if="docSelectorOpen" class="absolute top-full left-0 mt-1 w-72 bg-white border border-gray-200 rounded-xl shadow-xl z-30 overflow-hidden">\n                <div class="px-3 py-2 border-b bg-gray-50 flex items-center justify-between">\n                  <span class="text-xs font-semibold text-gray-500">\xeb\xac\xb8\xec\x84\x9c \xec\x84\xa0\xed\x83\x9d (\xeb\xb3\xb5\xec\x88\x98 \xea\xb0\x80\xeb\x8a\xa5)</span>\n                  <button @click="selectedDocIds = []" class="text-xs text-gray-400 hover:text-red-500">\xec\xa0\x84\xec\xb2\xb4 \xed\x95\xb4\xec\xa0\x9c</button>\n                </div>\n                <div class="max-h-56 overflow-y-auto">\n                  <label v-for="doc in documents" :key="doc.id"\n                    class="flex items-center gap-3 px-4 py-2.5 hover:bg-purple-50 cursor-pointer transition-colors"\n                    :class="selectedDocIds.includes(doc.id) ? \'bg-purple-50\' : \'\'">\n                    <input type="checkbox" :value="doc.id" v-model="selectedDocIds" class="accent-purple-600 w-4 h-4 flex-shrink-0">\n                    <span class="text-sm truncate" :title="doc.filename">{{ doc.filename }}</span>\n                  </label>\n                  <div v-if="documents.length === 0" class="px-4 py-3 text-sm text-gray-400 text-center">\xeb\xac\xb8\xec\x84\x9c\xea\xb0\x80 \xec\x97\x86\xec\x8a\xb5\xeb\x8b\x88\xeb\x8b\xa4</div>\n                </div>\n              </div>\n            </div>\n          </div>\n          <div class="flex items-center gap-2">\n            <span class="text-sm font-medium text-gray-500">\xeb\xaa\xa8\xeb\x8d\xb8:</span>\n            <select v-model="selectedProvider" class="border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-purple-500">\n              <option v-for="m in availableModels" :key="m.id" :value="m.id">{{ m.name }}{{ m.badge ? \' [\' + m.badge + \']\' : \'\' }}</option>\n            </select>\n          </div>\n          <button @click="generateQuestions" :disabled="selectedDocIds.length === 0 || generating"\n            class="bg-purple-600 text-white px-5 py-2 rounded-lg font-semibold hover:bg-purple-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center gap-2">\n            <span v-if="generating" class="animate-spin inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full"></span>\n            {{ generating ? \'AI\xea\xb0\x80 \xeb\xac\xb8\xec\xa0\x9c\xeb\xa5\xbc \xec\x83\x9d\xec\x84\xb1 \xec\xa4\x91...\' : \'\xeb\xac\xb8\xec\xa0\x9c \xec\x83\x9d\xec\x84\xb1\xed\x95\x98\xea\xb8\xb0\' }}\n          </button>\n          <button v-if="questions.length > 0" @click="clearQuestions"\n            class="bg-gray-200 text-gray-700 px-5 py-2 rounded-lg font-semibold hover:bg-gray-300 transition-colors">\xeb\xac\xb8\xec\xa0\x9c \xeb\xb9\x84\xec\x9a\xb0\xea\xb8\xb0</button>\n          <button v-if="hasWrongQuestions && !quizStarted && !finished" @click="startReview"\n            class="bg-red-100 text-red-700 px-5 py-2 rounded-lg font-semibold hover:bg-red-200 transition-colors">\xed\x8b\x80\xeb\xa6\xb0 \xeb\xac\xb8\xec\xa0\x9c \xeb\xb3\xb5\xec\x8a\xb5\xed\x95\x98\xea\xb8\xb0</button>\n        </div>\n        <p v-if="selectedModelBadge" class="mt-1.5 text-[11px] text-amber-600 flex items-center gap-1">\n          <span>\xe2\x9a\xa0</span>\n          <span v-if="selectedModelBadge === \'\xeb\xac\xb4\xeb\xa3\x8c\'">\xeb\xac\xb4\xeb\xa3\x8c \xeb\xaa\xa8\xeb\x8d\xb8\xec\x9d\x80 API \xed\x98\xb8\xec\xb6\x9c \xed\x95\x9c\xeb\x8f\x84 \xec\xb4\x88\xea\xb3\xbc \xec\x8b\x9c \xec\x9d\x91\xeb\x8b\xb5\xec\x9d\xb4 \xec\xa0\x9c\xed\x95\x9c\xeb\x90\xa0 \xec\x88\x98 \xec\x9e\x88\xec\x8a\xb5\xeb\x8b\x88\xeb\x8b\xa4.</span>\n          <span v-else-if="selectedModelBadge === \'\xeb\xac\xb4\xeb\xa3\x8c\xed\x8b\xb0\xec\x96\xb4\'">\xeb\xac\xb4\xeb\xa3\x8c \xed\x8b\xb0\xec\x96\xb4 \xeb\xaa\xa8\xeb\x8d\xb8\xec\x9d\x80 \xec\x9b\x94\xeb\xb3\x84 \xed\x81\xac\xeb\xa0\x88\xeb\x94\x67 \xec\x86\x8c\xec\xa7\x84 \xec\x8b\x9c \xeb\x8f\x99\xec\x9e\x91\xed\x95\x98\xec\xa7\x80 \xec\x95\x8a\xec\x9d\x84 \xec\x88\x98 \xec\x9e\x88\xec\x8a\xb5\xeb\x8b\x88\xeb\x8b\xa4.</span>\n        </p>\n      </div>\n\n      <!-- \xeb\xb9\x88 \xec\x83\x81\xed\x83\x9c -->\n      <div v-if="!generating && questions.length === 0 && selectedDocIds.length > 0" class="bg-gray-50 rounded-xl p-8 text-center text-gray-400">\xec\x84\xa0\xed\x83\x9d\xed\x95\x9c \xeb\xac\xb8\xec\x84\x9c\xec\x9d\x98 \xeb\xac\xb8\xec\xa0\x9c\xea\xb0\x80 \xec\x97\x86\xec\x8a\xb5\xeb\x8b\x88\xeb\x8b\xa4. "\xeb\xac\xb8\xec\xa0\x9c \xec\x83\x9d\xec\x84\xb1\xed\x95\x98\xea\xb8\xb0"\xeb\xa5\xbc \xed\x81\xb4\xeb\xa6\xad\xed\x95\x98\xec\x84\xb8\xec\x9a\x94.</div>\n      <div v-if="selectedDocIds.length === 0" class="bg-gray-50 rounded-xl p-8 text-center text-gray-400">\xeb\xac\xb8\xec\x84\x9c\xeb\xa5\xbc \xed\x95\x98\xeb\x82\x98 \xec\x9d\xb4\xec\x83\x81 \xec\x84\xa0\xed\x83\x9d\xed\x95\x98\xeb\xa9\xb4 \xeb\xac\xb8\xec\xa0\x9c\xeb\xa5\xbc \xeb\xb6\x88\xeb\x9f\xac\xec\x98\xa4\xea\xb1\xb0\xeb\x82\x98 \xec\x83\x9d\xec\x84\xb1\xed\x95\xa0 \xec\x88\x98 \xec\x9e\x88\xec\x8a\xb5\xeb\x8b\x88\xeb\x8b\xa4.</div>\n\n      <!-- \xed\x80\xb4\xec\xa6\x88 \xec\x8b\x9c\xec\x9e\x91 \xec\xa0\x84 \xeb\xaa\xa9\xeb\xa1\xed -->\n      <div v-if="questions.length > 0 && !quizStarted && !finished" class="space-y-4">\n        <div class="bg-white rounded-xl shadow p-5 flex items-center justify-between">\n          <div>\n            <p class="font-semibold text-gray-700">\xec\xb4\x9d {{ questions.length }}\xeb\xac\xb8\xec\xa0\x9c</p>\n            <p class="text-sm text-gray-400 mt-0.5">\xec\xa0\x95\xeb\x8b\xb5 {{ solvedCount }}\xea\xb0\x9c \xc2\xb7 \xec\x98\xa4\xeb\x8b\xb5 {{ wrongCount }}\xea\xb0\x9c \xc2\xb7 \xec\x8b\xa0\xea\xb7\x9c {{ newCount }}\xea\xb0\x9c</p>\n          </div>\n          <button @click="startQuiz(false)" class="bg-purple-600 text-white px-6 py-2.5 rounded-lg font-semibold hover:bg-purple-700 transition-colors">\xec\xa0\x84\xec\xb2\xb4 \xed\x92\x80\xea\xb8\xb0 \xe2\x86\x92</button>\n        </div>\n        <div v-for="(q, i) in questions" :key="q.id" class="bg-white rounded-xl shadow px-5 py-3 flex items-center justify-between">\n          <div class="flex items-center gap-3">\n            <span class="text-sm font-bold text-purple-500">Q{{ i + 1 }}</span>\n            <span class="text-sm text-gray-700 truncate max-w-lg">{{ q.question }}</span>\n          </div>\n          <span class="text-[11px] font-bold px-2 py-0.5 rounded-full flex-shrink-0"\n            :class="q.status === \'solved\' ? \'bg-green-100 text-green-700\' : q.status === \'wrong\' ? \'bg-red-100 text-red-700\' : \'bg-gray-100 text-gray-500\'">\n            {{ q.status === \'solved\' ? \'\xe2\x9c\x93 \xec\x99\x84\xeb\xa3\x8c\' : q.status === \'wrong\' ? \'\xe2\x9c\x97 \xec\x98\xa4\xeb\x8b\xb5\' : \'\xeb\xaf\xb8\xed\x92\x80\xec\x9d\xb4\' }}\n          </span>\n        </div>\n      </div>\n\n      <!-- \xed\x80\xb4\xec\xa6\x88 \xec\xa7\x84\xed\x96\x89 \xec\xa4\x91 -->\n      <div v-if="quizStarted && !finished && currentQ">\n        <!-- \xec\x83\x81\xeb\x8b\xa8 \xec\xa7\x84\xed\x96\x89/\xec\xa0\x95\xeb\x8b\xb5\xeb\xa5\xa0 \xeb\xb0\x94 -->\n        <div class="bg-white rounded-xl shadow p-4 mb-4 flex items-center gap-4">\n          <div class="flex-1">\n            <div class="flex items-center justify-between text-xs text-gray-500 mb-1">\n              <span>\xec\xa7\x84\xed\x96\x89\xeb\xa5\xa0</span>\n              <span>{{ currentIdx + 1 }} / {{ activeQuestions.length }}</span>\n            </div>\n            <div class="w-full bg-gray-100 rounded-full h-2">\n              <div class="bg-purple-500 h-2 rounded-full transition-all" :style="{width: (currentIdx / activeQuestions.length * 100) + \'%\'}"></div>\n            </div>\n          </div>\n          <div class="text-center flex-shrink-0">\n            <p class="text-xs text-gray-400">\xec\xa0\x95\xeb\x8b\xb5\xeb\xa5\xa0</p>\n            <p class="text-xl font-bold" :class="accuracy >= 70 ? \'text-green-600\' : accuracy >= 50 ? \'text-amber-500\' : \'text-red-500\'">\n              {{ accuracy }}%\n            </p>\n            <p class="text-[10px] text-gray-400">{{ score.correct }} / {{ score.total }}</p>\n          </div>\n        </div>\n\n        <!-- \xeb\xac\xb8\xec\xa0\x9c \xec\xb9\xb4\xeb\x93\x9c -->\n        <div class="bg-white rounded-xl shadow p-6">\n          <p class="font-semibold text-gray-800 text-base mb-5">\n            <span class="text-purple-600 mr-2">Q{{ currentIdx + 1 }}.</span>{{ currentQ.question }}\n          </p>\n\n          <!-- \xed\x9e\x8c\xed\x8a\xb8 -->\n          <div v-if="!answered" class="mb-4">\n            <button @click="showHint = !showHint"\n              class="text-xs text-amber-600 border border-amber-300 bg-amber-50 px-3 py-1 rounded-lg hover:bg-amber-100 transition-colors flex items-center gap-1">\n              <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.362.362A9.003 9.003 0 0112 21a9.003 9.003 0 01-4.774-1.331l-.362-.362z"/></svg>\n              {{ showHint ? \'\xed\x9e\x8c\xed\x8a\xb8 \xec\x88\xa8\xea\xb8\xb0\xea\xb8\xb0\' : \'\xed\x9e\x8c\xed\x8a\xb8 \xeb\xb3\xb4\xea\xb8\xb0\' }}\n            </button>\n            <div v-if="showHint" class="mt-2 px-4 py-2.5 bg-amber-50 border border-amber-200 rounded-lg text-sm text-amber-800">\n              {{ currentQ.hint || \'\xec\xa0\x95\xeb\x8b\xb5\xec\x9d\x84 \xec\x84\xa0\xed\x83\x9d\xec\xa7\x80\xec\x97\x90\xec\x84\x9c \xec\x8b\xa0\xec\xa4\x91\xed\x95\x98\xea\xb2\x8c \xea\xb3\xa8\xeb\x9d\xbc\xeb\xb3\xb4\xec\x84\xb8\xec\x9a\x94.\' }}\n            </div>\n          </div>\n\n          <!-- \xec\x84\xa0\xed\x83\x9d\xec\xa7\x80 -->\n          <div class="space-y-2 mb-5">\n            <label v-for="choice in currentQ.choices" :key="choice"\n              class="flex items-center gap-3 p-3 rounded-lg border cursor-pointer transition-colors"\n              :class="choiceClass(choice)">\n              <input type="radio" :name="\'q\' + currentQ.id" :value="choice" v-model="currentAnswer" :disabled="answered" class="accent-purple-600 flex-shrink-0">\n              <span class="text-sm flex-1">{{ choice }}</span>\n              <span v-if="answered && choice === currentResult.correct_answer" class="text-green-600 text-xs font-bold flex-shrink-0">\xe2\x9c\x93 \xec\xa0\x95\xeb\x8b\xb5</span>\n              <span v-if="answered && choice === currentAnswer && choice !== currentResult.correct_answer" class="text-red-500 text-xs font-bold flex-shrink-0">\xe2\x9c\x97</span>\n            </label>\n          </div>\n\n          <!-- \xec\xa0\x9c\xec\xb6\x9c \xec\xa0\x84 \xeb\xb2\x84\xed\x8a\xbc -->\n          <div v-if="!answered" class="flex justify-end">\n            <button @click="submitCurrent" :disabled="!currentAnswer || submitting"\n              class="bg-purple-600 text-white px-8 py-2.5 rounded-lg font-semibold hover:bg-purple-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center gap-2">\n              <span v-if="submitting" class="animate-spin inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full"></span>\n              \xec\xa0\x9c\xec\xb6\x9c\n            </button>\n          </div>\n\n          <!-- \xea\xb2\xb0\xea\xb3\xbc \xed\x94\xbc\xeb\x93\x9c\xeb\xb0\xb1 -->\n          <div v-if="answered" class="mt-1">\n            <div class="p-3 rounded-lg text-sm font-semibold mb-4"\n              :class="currentResult.is_correct ? \'bg-green-50 text-green-700 border border-green-200\' : \'bg-red-50 text-red-700 border border-red-200\'">\n              {{ currentResult.is_correct ? \'\xe2\x9c\x93 \xec\xa0\x95\xeb\x8b\xb5\xec\x9e\x85\xeb\x8b\x88\xeb\x8b\xa4!\' : \'\xe2\x9c\x97 \xec\x98\xa4\xeb\x8b\xb5\xec\x9e\x85\xeb\x8b\x88\xeb\x8b\xa4. \xec\xa0\x95\xeb\x8b\xb5: \' + currentResult.correct_answer }}\n            </div>\n            <div class="flex justify-end">\n              <button v-if="currentIdx < activeQuestions.length - 1" @click="nextQuestion"\n                class="bg-purple-600 text-white px-8 py-2.5 rounded-lg font-semibold hover:bg-purple-700 transition-colors">\n                \xeb\x8b\xa4\xec\x9d\x8c \xeb\xac\xb8\xec\xa0\x9c \xe2\x86\x92\n              </button>\n              <button v-else @click="finishQuiz"\n                class="bg-green-600 text-white px-8 py-2.5 rounded-lg font-semibold hover:bg-green-700 transition-colors">\n                \xea\xb2\xb0\xea\xb3\xbc \xeb\xb3\xb4\xea\xb8\xb0\n              </button>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- \xea\xb2\xb0\xea\xb3\xbc \xed\x99\x94\xeb\xa9\xb4 -->\n      <div v-if="finished" class="bg-white rounded-xl shadow p-8 text-center">\n        <div class="text-5xl mb-4">{{ score.correct / score.total >= 0.8 ? \'\xf0\x9f\x8e\x89\' : score.correct / score.total >= 0.5 ? \'\xf0\x9f\x91\x8d\' : \'\xf0\x9f\x93\x96\' }}</div>\n        <p class="text-2xl font-bold mb-1" :class="score.correct / score.total >= 0.7 ? \'text-green-600\' : \'text-orange-500\'">\n          {{ score.total }}\xeb\xac\xb8\xec\xa0\x9c \xec\xa4\x91 {{ score.correct }}\xeb\xac\xb8\xec\xa0\x9c \xec\xa0\x95\xeb\x8b\xb5\n        </p>\n        <p class="text-4xl font-black mb-6" :class="score.correct / score.total >= 0.7 ? \'text-green-500\' : \'text-orange-400\'">\n          {{ Math.round(score.correct / score.total * 100) }}%\n        </p>\n        <div class="flex justify-center gap-3">\n          <button @click="startQuiz(false)" class="bg-purple-600 text-white px-6 py-2.5 rounded-lg font-semibold hover:bg-purple-700 transition-colors">\xec\xa0\x84\xec\xb2\xb4 \xeb\x8b\xa4\xec\x8b\x9c \xed\x92\x80\xea\xb8\xb0</button>\n          <button v-if="hasWrongQuestions" @click="startReview" class="bg-red-100 text-red-700 px-6 py-2.5 rounded-lg font-semibold hover:bg-red-200 transition-colors">\xed\x8b\x80\xeb\xa6\xb0 \xeb\xac\xb8\xec\xa0\x9c\xeb\xa7\x8c \xeb\xb3\xb5\xec\x8a\xb5</button>\n          <button @click="resetToList" class="bg-gray-100 text-gray-700 px-6 py-2.5 rounded-lg font-semibold hover:bg-gray-200 transition-colors">\xeb\xaa\xa9\xeb\xa1\xed\x81\xac\xeb\xa1\x9c</button>\n        </div>\n      </div>\n    </div>\n  `,\n  setup() {\n    const route            = VueRouter.useRoute();\n    const documents        = ref([]);\n    const selectedDocIds   = ref([]);\n    const docSelectorOpen  = ref(false);\n    const selectedProvider = ref('openai');\n    const availableModels  = ref([]);\n    const questions        = ref([]);\n    const generating       = ref(false);\n    const submitting       = ref(false);\n\n    // \xed\x80\xb4\xec\xa6\x88 \xec\xa7\x84\xed\x96\x89 \xec\x83\x81\xed\x83\x9c\n    const quizStarted     = ref(false);\n    const finished        = ref(false);\n    const activeQuestions = ref([]);\n    const currentIdx      = ref(0);\n    const currentAnswer   = ref('');\n    const answered        = ref(false);\n    const currentResult   = ref(null);\n    const showHint        = ref(false);\n    const score           = ref({ correct: 0, total: 0 });\n\n    const currentQ        = Vue.computed(() => activeQuestions.value[currentIdx.value] || null);\n    const accuracy        = Vue.computed(() => score.value.total > 0 ? Math.round(score.value.correct / score.value.total * 100) : 0);\n    const hasWrongQuestions = Vue.computed(() => questions.value.some(q => q.status === 'wrong'));\n    const solvedCount     = Vue.computed(() => questions.value.filter(q => q.status === 'solved').length);\n    const wrongCount      = Vue.computed(() => questions.value.filter(q => q.status === 'wrong').length);\n    const newCount        = Vue.computed(() => questions.value.filter(q => q.status === 'new').length);\n\n    const fetchQuestions = async (docIds) => {\n      if (!docIds || docIds.length === 0) { questions.value = []; return; }\n      try {\n        const params = {};\n        if (docIds.length === 1) params.document_id = docIds[0];\n        const res = await axios.get(`${API_URL}/api/questions`, { params });\n        questions.value = res.data;\n      } catch (e) { console.error(e); }\n    };\n\n    watch(selectedDocIds, async (newIds) => {\n      resetToList();\n      await fetchQuestions(newIds);\n    });\n\n    const generateQuestions = async () => {\n      if (selectedDocIds.value.length === 0 || generating.value) return;\n      generating.value = true;\n      resetToList();\n      try {\n        await axios.post(`${API_URL}/api/questions/generate`,\n          { document_ids: selectedDocIds.value },\n          { params: { provider: selectedProvider.value } }\n        );\n        await fetchQuestions(selectedDocIds.value);\n      } catch (e) {\n        alert('\xeb\xac\xb8\xec\xa0\x9c \xec\x83\x9d\xec\x84\xb1 \xec\x8b\xa4\xed\x8c\xa8: ' + (e.response?.data?.detail || e.message));\n      } finally {\n        generating.value = false;\n      }\n    };\n\n    const clearQuestions = async () => {\n      if (selectedDocIds.value.length === 0) return;\n      if (!confirm('\xec\x84\xa0\xed\x83\x9d\xed\x95\x9c \xeb\xac\xb8\xec\x84\x9c\xec\x99\x80 \xea\xb4\x80\xeb\xa0\xa8\xeb\x90\x9c \xeb\xaa\xa8\xeb\x93\xa0 \xeb\xac\xb8\xec\xa0\x9c\xeb\xa5\xbc \xec\x82\xad\xec\xa0\x9c\xed\x95\x98\xec\x8b\x9c\xea\xb2\xa0\xec\x8a\xb5\xeb\x8b\x88\xea\xb9\x8c?')) return;\n      try {\n        for (const docId of selectedDocIds.value) {\n          await axios.delete(`${API_URL}/api/questions`, { params: { document_id: docId } });\n        }\n        questions.value = [];\n        resetToList();\n      } catch (e) {\n        alert('\xec\x82\xad\xec\xa0\x9c \xec\x8b\xa4\xed\x8c\xa8: ' + (e.response?.data?.detail || e.message));\n      }\n    };\n\n    const startQuiz = (wrongOnly) => {\n      activeQuestions.value = wrongOnly\n        ? questions.value.filter(q => q.status === 'wrong')\n        : [...questions.value];\n      currentIdx.value    = 0;\n      currentAnswer.value = '';\n      answered.value      = false;\n      currentResult.value = null;\n      showHint.value      = false;\n      score.value         = { correct: 0, total: 0 };\n      quizStarted.value   = true;\n      finished.value      = false;\n    };\n\n    const startReview = () => startQuiz(true);\n\n    const submitCurrent = async () => {\n      if (!currentAnswer.value || answered.value || submitting.value) return;\n      submitting.value = true;\n      try {\n        const res = await axios.post(`${API_URL}/api/questions/attempt`, {\n          question_id: currentQ.value.id,\n          user_answer: currentAnswer.value,\n        });\n        currentResult.value = res.data;\n        answered.value = true;\n        score.value.total++;\n        if (res.data.is_correct) score.value.correct++;\n      } catch (e) {\n        alert('\xec\xb1\x84\xec\xa0\x90 \xec\x98\xa4\xeb\xa5\x98: ' + (e.response?.data?.detail || e.message));\n      } finally {\n        submitting.value = false;\n      }\n    };\n\n    const nextQuestion = () => {\n      currentIdx.value++;\n      currentAnswer.value = '';\n      answered.value      = false;\n      currentResult.value = null;\n      showHint.value      = false;\n    };\n\n    const finishQuiz = async () => {\n      finished.value = true;\n      await fetchQuestions(selectedDocIds.value);\n    };\n\n    const resetToList = () => {\n      quizStarted.value   = false;\n      finished.value      = false;\n      activeQuestions.value = [];\n      currentIdx.value    = 0;\n      currentAnswer.value = '';\n      answered.value      = false;\n      currentResult.value = null;\n      showHint.value      = false;\n      score.value         = { correct: 0, total: 0 };\n    };\n\n    const choiceClass = (choice) => {\n      if (!answered.value) {\n        return currentAnswer.value === choice\n          ? 'border-purple-400 bg-purple-50'\n          : 'border-gray-200 hover:border-purple-300 hover:bg-purple-50';\n      }\n      if (choice === currentResult.value?.correct_answer) return 'border-green-400 bg-green-50';\n      if (choice === currentAnswer.value && choice !== currentResult.value?.correct_answer) return 'border-red-300 bg-red-50';\n      return 'border-gray-200 opacity-50';\n    };\n\n    onMounted(async () => {\n      try {\n        const [docRes, modelRes] = await Promise.all([\n          axios.get(`${API_URL}/api/documents`),\n          axios.get(`${API_URL}/api/available-models`)\n        ]);\n        documents.value = docRes.data;\n        availableModels.value = modelRes.data;\n        if (route.query.provider) {\n          selectedProvider.value = route.query.provider;\n        } else if (availableModels.value.length > 0) {\n          selectedProvider.value = availableModels.value[0].id;\n        }\n      } catch (e) { console.error(e); }\n\n      if (route.query.document_ids) {\n        selectedDocIds.value = route.query.document_ids.split(',').map(Number);\n      } else if (route.query.document_id) {\n        selectedDocIds.value = [parseInt(route.query.document_id)];\n      }\n    });\n\n    const selectedModelBadge = Vue.computed(() => {\n      const m = availableModels.value.find(m => m.id === selectedProvider.value);\n      return m?.badge || '';\n    });\n\n    return {\n      documents, selectedDocIds, docSelectorOpen, selectedProvider, availableModels,\n      questions, generating, submitting,\n      quizStarted, finished, activeQuestions, currentIdx, currentAnswer, answered, currentResult, showHint, score,\n      currentQ, accuracy, hasWrongQuestions, solvedCount, wrongCount, newCount,\n      generateQuestions, clearQuestions, startQuiz, startReview, submitCurrent, nextQuestion, finishQuiz, resetToList, choiceClass, selectedModelBadge,\n    };\n  }\n};\n"""

with open('frontend/app.js', 'rb') as f:
    content = f.read()

start_bytes = b'// \xe2\x94\x80\xe2\x94\x80\xe2\x94\x80 Questions '
end_bytes   = b'// \xe2\x94\x80\xe2\x94\x80\xe2\x94\x80 AdminDashboard'

si = content.index(start_bytes)
ei = content.index(end_bytes)

new_content = content[:si] + new_section + b'\r\n' + content[ei:]
with open('frontend/app.js', 'wb') as f:
    f.write(new_content)
print(f"Done. {si} -> {ei}, new length={len(new_content)}")